def outer():
    x = 10
    def inner():
        return x + 1          # read the outer one
    return inner()

print(outer())

def counter():
    n = 0
    def inc():
        nonlocal n
        n += 1
        return n
    return inc

c = counter()
print(c(), c(), c())

import time

def timer(func):
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        print(f"{func.__name__}: done")
        return result
    return wrapper

@timer
def square(x):
    return x * x

print(square(7))

def logged(func):
    def wrapper(*args, **kwargs):
        print("call", args, kwargs)
        return func(*args, **kwargs)
    return wrapper

@logged
def add(a, b=0):
    return a + b

print(add(1, b=2))

from functools import wraps

def deco(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@deco
def hello():
    """Say hello."""

print(hello.__name__, hello.__doc__)

def repeat(times):
    def decorator(func):
        def wrapper(*args, **kwargs):
            result = None
            for _ in range(times):
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator

@repeat(3)
def hello():
    print("hello")

hello()

def memo(func):
    cache = {}
    def wrapper(n):
        if n not in cache:
            cache[n] = func(n)
        return cache[n]
    return wrapper

@memo
def slow_square(n):
    print("computing", n)
    return n * n

print(slow_square(4), slow_square(4))

class CountCalls:
    def __init__(self, func):
        self.func = func
        self.calls = 0
    def __call__(self, *args, **kwargs):
        self.calls += 1
        return self.func(*args, **kwargs)

@CountCalls
def hi():
    return "hello"

hi()
hi()
print(hi.calls, hi())

def broken(func):
    def wrapper(*args, **kwargs):
        func(*args, **kwargs)          # forgot return
    return wrapper

@broken
def one():
    return 1

print(one())
